class Node { constructor(key){ this.key=key; this.cnt=1; this.size=1; this.left=null; this.right=null; this.pri=Math.random(); } }
function upd(n){ if(n) n.size = n.cnt + (n.left?.size||0) + (n.right?.size||0); }
function insert(n, key){ /* standard Treap insert logic with cnt handling */ }
function erase(n, key){ /* decrement cnt; remove node if cnt==0; update sizes */ }
function rank(n, key){ if(!n) return 0; if(key <= n.key) return rank(n.left, key); return (n.left?.size||0) + n.cnt + rank(n.right, key); }
function kth(n, k){ if(!n) return null; const ls = n.left?.size||0; if(k <= ls) return kth(n.left, k); if(k <= ls + n.cnt) return n.key; return kth(n.right, k - ls - n.cnt); }
